// grid puzzle core: W x H cells, pockets at corners + middle of long sides
var PZ=(function(){
  var W=9,H=5,POCK=[[0,0],[4,0],[8,0],[0,4],[4,4],[8,4]],DIRS={u:[0,-1],d:[0,1],l:[-1,0],r:[1,0]};
  function isP(x,y){for(var i=0;i<6;i++)if(POCK[i][0]===x&&POCK[i][1]===y)return true;return false;}
  // st: {b:{0:[x,y],1:[x,y],...}, gone:[n...]} ; L:{blocks:[[x,y]]}
  function shoot(L,st,dir){var d=DIRS[dir],b={},k;for(k in st.b)b[k]=st.b[k].slice();var gone=st.gone.slice(),ev=[],m='0',moved=false;
    var occ=function(x,y){for(var q in b)if(b[q][0]===x&&b[q][1]===y)return q;return null;};
    var blk=function(x,y){return (L.blocks||[]).some(function(c){return c[0]===x&&c[1]===y;});};
    for(var guard=0;guard<50;guard++){var p=b[m],from=p.slice();
      while(true){var nx=p[0]+d[0],ny=p[1]+d[1];
        if(nx<0||ny<0||nx>=W||ny>=H||blk(nx,ny)){ if(p[0]!==from[0]||p[1]!==from[1]){ev.push({n:m,from:from,to:p.slice()});moved=true;} return done();}
        if(isP(nx,ny)){ev.push({n:m,from:from,to:[nx,ny],fall:true});moved=true;delete b[m];gone.push(+m);return done();}
        var o=occ(nx,ny);if(o!==null){if(p[0]!==from[0]||p[1]!==from[1]){ev.push({n:m,from:from,to:p.slice()});}ev.push({n:m,hit:o});moved=true;m=o;break;}
        p[0]=nx;p[1]=ny;}}
    function done(){return {st:{b:b,gone:gone},ev:ev,moved:moved};}
    return done();}
  // judge after shot: returns 'win' | 'fail:reason' | 'ok'
  function judge(L,prev,st){var newly=st.gone.filter(function(n){return prev.gone.indexOf(n)<0;});
    if(newly.indexOf(0)>=0)return 'fail:scratch';
    var all=L.balls.map(function(x){return x[2];});
    if(L.rule==='order'){var rem=all.filter(function(n){return prev.gone.indexOf(n)<0;}).sort(function(a,b){return a-b;});
      for(var i=0;i<newly.length;i++){if(newly[i]!==rem[0])return 'fail:order';rem.shift();}}
    if(L.rule==='eight'){var left=all.filter(function(n){return n!==8&&st.gone.indexOf(n)<0;});if(newly.indexOf(8)>=0&&left.length)return 'fail:eight';}
    var remain=all.filter(function(n){return st.gone.indexOf(n)<0;});return remain.length?'ok':'win';}
  function init(L){var b={0:L.cue.slice()};L.balls.forEach(function(x){b[x[2]]=[x[0],x[1]];});return {b:b,gone:[]};}
  function key(st){var ks=Object.keys(st.b).sort();return ks.map(function(k){return k+':'+st.b[k].join(',');}).join('|')+'#'+st.gone.slice().sort().join(',');}
  function solve(L,maxD){var s0=init(L),q=[[s0,'']],seen={};seen[key(s0)]=1;
    while(q.length){var cur=q.shift(),st=cur[0],path=cur[1];if(path.length>=maxD)continue;
      for(var dir in DIRS){var r=shoot(L,st,dir);if(!r.moved)continue;var j=judge(L,st,r.st);if(j==='win')return path+dir;if(j!=='ok')continue;
        var k=key(r.st);if(seen[k])continue;seen[k]=1;q.push([r.st,path+dir]);}}
    return null;}
  return {W:W,H:H,POCK:POCK,isP:isP,shoot:shoot,judge:judge,init:init,solve:solve};
})();
