  function rackShot(){if(RG.over)return;var cur=RG.cur,low=rg_lowest(),g=RG.groups[cur],onEight=RG.kind===8&&!!g&&rg_left(g)===0,brk=RG.brk;
    var speed=brk&&POW===2?320:SIM.SPEEDS[POW],st=SIM.shootBalls(BALLS,ANG,speed);BALLS=st.balls;RG.shots[cur]++;RG.inHand=false;el('gmTry').textContent=RG.shots[cur];el('gmShot').disabled=true;
    var reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
    ANIM=true;(function frame(){var moving=true,n=reduce?40:4;for(var k=0;k<n&&moving;k++)moving=SIM.step(st);draw();
      if(moving){requestAnimationFrame(frame);return;}ANIM=null;el('gmShot').disabled=false;rackJudge(st,cur,low,g,onEight,brk);})();}
  function rackJudge(st,cur,low,g,onEight,brk){var pk=[];st.events.forEach(function(e){if(e.t==='pocket'&&e.n!==0&&pk.indexOf(e.n)<0)pk.push(e.n);});
    var cueIn=BALLS[0].in,first=st.first,foul=false,why='',note='',ball=function(n){return BALLS.filter(function(b){return b.n===n;})[0];};
    if(first==null){foul=true;why='どの球にも当たりませんでした';}
    if(RG.kind===9){
      if(!foul&&first!==low){foul=true;why='最初に当たったのが'+first+'番でした。'+low+'番に最初に当てよう';}
      if(cueIn){foul=true;why=why?why+'。手球も落ちました':'手球がポケットに落ちました';}
      if(pk.indexOf(9)>=0){if(!foul)return endGame('🎉 9番イン！ '+(RG.players===2?'<b>'+rg_pname(cur)+'の勝ち！</b>':'<b>クリア！</b> ショット'+RG.shots[0]+'回・ファウル'+RG.fouls[0]+'回でした。'));rg_spot(rg_ball(9),150,50);note='（9番は台にもどします）';}
    }else{
      if(!foul&&!brk){if(!g){if(first===8){foul=true;why='組が決まる前は、8番に最初に当ててはいけません';}}
        else if(onEight){if(first!==8){foul=true;why='自分の球は全部入ったので、8番に最初に当てよう';}}
        else if(rg_grp(first)!==g){foul=true;why='最初に当たったのが相手の球（'+first+'番）でした';}}
      if(cueIn){foul=true;why=why?why+'。手球も落ちました':'手球がポケットに落ちました';}
      if(pk.indexOf(8)>=0){
        if(brk){rg_spot(rg_ball(8),150,50);note='（ブレイクで入った8番は台にもどします）';}
        else if(onEight&&!foul)return endGame('🎉 8番イン！ '+(RG.players===2?'<b>'+rg_pname(cur)+'の勝ち！</b>':'<b>クリア！</b> ショット'+RG.shots[0]+'回・ファウル'+RG.fouls[0]+'回でした。'));
        else{var r=foul?'ファウルのときに8番が入ってしまいました':'自分の球が残っているのに8番が入ってしまいました';return endGame(RG.players===2?r+'。<b>'+rg_pname(1-cur)+'の勝ち！</b>':'ざんねん！ '+r+'。');}}
      if(!foul&&!brk&&!g){for(var i=0;i<pk.length;i++){var fg=rg_grp(pk[i]);if(fg){RG.groups[cur]=fg;RG.groups[1-cur]=fg==='solid'?'stripe':'solid';note+='（'+rg_pname(cur)+'は'+GN[fg]+'に決まりました）';break;}}}
    }
    RG.brk=false;if(cueIn)rg_spot(BALLS[0],45,50);
    var gg=RG.groups[cur],cont=!foul&&(RG.kind===9?pk.length>0:gg?pk.some(function(n){return rg_grp(n)===gg;}):pk.some(function(n){return n!==8;}));
    if(foul){RG.fouls[cur]++;RG.cur=RG.players===2?1-cur:cur;RG.inHand=true;rMsg('ファウル！ '+why+'。'+note+'<br><b>'+rg_pname(RG.cur)+'</b>の番。手球を好きな場所に置けます（手球をドラッグ）。');}
    else if(cont){rMsg('ナイスショット！ '+pk.length+'個入りました'+note+'。'+(RG.players===2?'<b>'+rg_pname(cur)+'</b>がもう一度つけます。':'つづけてどうぞ。'));}
    else{if(RG.players===2)RG.cur=1-cur;rMsg((pk.length?'相手の球だけが入りました':'入りませんでした')+note+'。'+(RG.players===2?'<b>'+rg_pname(RG.cur)+'</b>の番です。':'つづけてどうぞ。'));}
    rg_aimTarget();renderScore();draw();}
  [].forEach.call(document.querySelectorAll('.gm-pp'),function(b){b.addEventListener('click',function(){if(ANIM)return;RG.players=+b.dataset.n;[].forEach.call(document.querySelectorAll('.gm-pp'),function(x){x.setAttribute('aria-checked',String(x===b));});rackNew();});});
