  function pzStages(){var box=el('pzStages'),open=pzOpen();box.innerHTML='';PZ_LEVELS.forEach(function(L,i){var b=document.createElement('button');b.type='button';b.className='gm-st';b.disabled=i>open;b.setAttribute('aria-current',String(i===PZS.lv));
    b.setAttribute('aria-label','パズル'+(i+1)+(i>open?'（まだ遊べません）':''));b.innerHTML='<b>'+(i+1)+'</b><small>'+starStr(S.pz[i+1]||0)+'</small>';b.addEventListener('click',function(){if(!PZS.busy)pzLoad(i);});box.appendChild(b);});}
  function pzLoad(i){PZS.lv=i;var L=PZ_LEVELS[i];PZS.st=PZ.init(L);PZS.hist=[];PZS.cnt=0;PZS.won=false;
    el('pzNo').textContent='LEVEL '+(i+1);el('pzName').textContent=L.name;el('pzStars').innerHTML=starStr(S.pz[i+1]||0);el('pzGoal').innerHTML=pzGoalText(L);el('pzPar').textContent=L.par;
    pzMsg(i===0?'矢印ボタンで、白い手球をつく向きを決めよう。台の上をスワイプしてもOK。':'めやすは '+L.par+' 回。考えてからつこう！');pzStages();pzDraw();}
