    var have=KT.filter(function(k){return S.kentei[k.r];}),top=have.length?have[have.length-1]:null;
    ktNow.innerHTML=top?'<span class="rk">'+top.r+'級</span><span>いまのあなたは <b>'+top.r+'級</b>（'+(+S.kentei[top.r].slice(5,7))+'月'+(+S.kentei[top.r].slice(8,10))+'日 合格）。'+(nx?'次は '+nx+'級「'+KT.filter(function(k){return k.r===nx;})[0].t+'」にチャレンジ！':'全部の級に合格しました。たまっこ名人です！')+'</span>':'<span class="rk">START</span><span>まだ記録がありません。まずは10級「はじめの一歩」から。</span>';
